import React, { useEffect, useRef, useState } from "react";

/* 0.4 — Learning. One ball, one hill. The maths here is real: the curve is
   f(x) = 0.05x⁴ − 0.6x² + 0.4x + 4 and the ball takes actual gradient steps
   at whatever learning rate you set. Push the rate past ~0.35 and it flies
   apart, which is the lesson. */

const f = (x) => 0.05 * x ** 4 - 0.6 * x ** 2 + 0.4 * x + 4;
const df = (x) => 0.2 * x ** 3 - 1.2 * x + 0.4;

const X_MIN = -4;
const X_MAX = 4;
const Y_MIN = 0;
const Y_MAX = 8;

const sx = (x) => ((x - X_MIN) / (X_MAX - X_MIN)) * 100;
const sy = (y) => 100 - ((y - Y_MIN) / (Y_MAX - Y_MIN)) * 100;

const CURVE = (() => {
  const pts = [];
  for (let x = X_MIN; x <= X_MAX; x += 0.08) pts.push(`${sx(x)},${sy(f(x))}`);
  return pts.join(" ");
})();

export default function GradientDescent() {
  const [lr, setLr] = useState(0.08);
  const [x, setX] = useState(-3.4);
  const [running, setRunning] = useState(false);
  const [steps, setSteps] = useState(0);
  const raf = useRef(null);
  const state = useRef({ x: -3.4, steps: 0 });

  const diverged = Math.abs(x) > 4.2 || !Number.isFinite(x);
  const settled = !diverged && Math.abs(df(x)) < 0.01 && steps > 3;

  useEffect(() => {
    if (!running) return undefined;
    let last = 0;
    const tick = (t) => {
      // ~12 steps/second — slow enough to watch the ball decide
      if (t - last > 80) {
        last = t;
        const s = state.current;
        s.x = s.x - lr * df(s.x);
        s.steps += 1;
        setX(s.x);
        setSteps(s.steps);
        if (Math.abs(s.x) > 4.2 || !Number.isFinite(s.x) || s.steps > 400) {
          setRunning(false);
          return;
        }
      }
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf.current);
  }, [running, lr]);

  const reset = (startX = -3.4) => {
    setRunning(false);
    state.current = { x: startX, steps: 0 };
    setX(startX);
    setSteps(0);
  };

  const drawX = Math.max(
    X_MIN,
    Math.min(X_MAX, Number.isFinite(x) ? x : X_MAX)
  );

  return (
    <div className="viz">
      <svg
        className="gd"
        viewBox="0 0 100 100"
        role="img"
        aria-label="A loss curve with a ball rolling downhill"
      >
        <polyline className="gd-curve" points={CURVE} />
        <line className="gd-axis" x1="0" y1={sy(0)} x2="100" y2={sy(0)} />
        <circle
          className={`gd-ball ${diverged ? "bad" : ""} ${
            settled ? "done" : ""
          }`}
          cx={sx(drawX)}
          cy={sy(f(drawX))}
          r="2.4"
        />
      </svg>

      <div className="viz-controls">
        <label className="viz-label" htmlFor="gd-lr">
          Learning rate <strong>{lr.toFixed(2)}</strong>
        </label>
        <input
          id="gd-lr"
          className="viz-range"
          type="range"
          min="0.01"
          max="0.6"
          step="0.01"
          value={lr}
          onChange={(e) => setLr(Number(e.target.value))}
        />
        <div className="viz-presets">
          <button
            type="button"
            className="viz-chip"
            onClick={() => setRunning((r) => !r)}
          >
            {running ? "Pause" : steps ? "Continue" : "Roll"}
          </button>
          <button
            type="button"
            className="viz-chip"
            onClick={() => reset(-3.4)}
          >
            Reset
          </button>
          <button type="button" className="viz-chip" onClick={() => reset(1.2)}>
            Start on the right
          </button>
        </div>
      </div>

      <p className="viz-note" aria-live="polite">
        {diverged ? (
          <>
            Diverged after {steps} steps. The rate was large enough that each
            correction overshot further than the last — this is what a loss
            going to NaN looks like from the inside.
          </>
        ) : settled ? (
          <>
            Settled after {steps} steps at x = {x.toFixed(2)}. Note{" "}
            <em>which</em> valley it found — start it on the right and it
            settles somewhere else entirely. Nothing guarantees the deeper one.
          </>
        ) : (
          <>
            Step {steps}. The ball only knows the slope directly under it. Turn
            the rate up past about 0.35 and watch it throw itself off the map.
          </>
        )}
      </p>
      <p className="viz-caveat">
        Real maths, toy landscape: one parameter instead of billions, but the
        failure mode is identical.
      </p>
    </div>
  );
}
