import React, { useMemo, useState } from "react";
import { SAMPLING_LOGITS } from "../learnViz";

/* 0.5 — Sampling. The softmax and the top-p cut are computed for real from
   the logits; only the logits themselves are invented. Slide temperature to
   0 and the model becomes a lookup table; slide it up and it starts
   suggesting cheese. */

export default function Sampling() {
  const [temp, setTemp] = useState(0.7);
  const [topP, setTopP] = useState(1);

  const rows = useMemo(() => {
    const t = Math.max(temp, 0.01);
    const scaled = SAMPLING_LOGITS.map((r) => r.logit / t);
    const max = Math.max(...scaled);
    const exps = scaled.map((s) => Math.exp(s - max));
    const sum = exps.reduce((a, b) => a + b, 0);
    const probs = SAMPLING_LOGITS.map((r, i) => ({
      ...r,
      p: exps[i] / sum,
    })).sort((a, b) => b.p - a.p);

    // top-p (nucleus): keep tokens until the cumulative mass reaches p
    let cum = 0;
    return probs.map((r) => {
      const kept = cum < topP;
      cum += r.p;
      return { ...r, kept };
    });
  }, [temp, topP]);

  const keptCount = rows.filter((r) => r.kept).length;
  const top = rows[0];

  return (
    <div className="viz">
      <div className="samp">
        {rows.map((r) => (
          <div key={r.token} className={`samp-row ${r.kept ? "" : "cut"}`}>
            <span className="samp-token">{r.token.replace(/ /g, "␣")}</span>
            <span className="samp-track">
              <span
                className="samp-fill"
                style={{ width: `${Math.max(r.p * 100, 0.4)}%` }}
              />
            </span>
            <span className="samp-pct">{(r.p * 100).toFixed(1)}%</span>
          </div>
        ))}
      </div>

      <div className="viz-controls two">
        <div>
          <label className="viz-label" htmlFor="samp-t">
            Temperature <strong>{temp.toFixed(2)}</strong>
          </label>
          <input
            id="samp-t"
            className="viz-range"
            type="range"
            min="0.01"
            max="2"
            step="0.01"
            value={temp}
            onChange={(e) => setTemp(Number(e.target.value))}
          />
        </div>
        <div>
          <label className="viz-label" htmlFor="samp-p">
            top-p <strong>{topP.toFixed(2)}</strong>
          </label>
          <input
            id="samp-p"
            className="viz-range"
            type="range"
            min="0.1"
            max="1"
            step="0.05"
            value={topP}
            onChange={(e) => setTopP(Number(e.target.value))}
          />
        </div>
      </div>

      <p className="viz-note" aria-live="polite">
        Prompt: <code>The capital of France is</code> — {keptCount} token
        {keptCount === 1 ? "" : "s"} eligible, “{top.token.trim()}” at{" "}
        {(top.p * 100).toFixed(1)}%.{" "}
        {temp < 0.2
          ? "At this temperature the model is effectively deterministic — which is what you want for extraction, classification and anything you'll parse."
          : temp > 1.2
          ? "At this temperature the tail is wide open. Creative, and occasionally cheese."
          : "The usual working range. Same weights, different nerve."}
      </p>
      <p className="viz-caveat">
        Softmax and the nucleus cut are computed live; the underlying logits are
        illustrative.
      </p>
    </div>
  );
}
