/* ============================================================
   JUMPING TO AN ANCHOR ON THIS SITE
   ------------------------------------------------------------
   Every obvious approach silently does nothing, and it took a
   while to work out why, so: the cause is `scroll-behavior:
   smooth` on <html> (global.js), NOT overflow:clip as the note
   in StackEdu.js assumes. The smooth animation is started and
   then interrupted — by a re-render, by the floating assistant's
   own scrollTo(0), by anything — and the page lands back at the
   top. Measured: an assignment settles at 15px instead of 5668.

   Forcing behaviour to `auto` for the duration of the assignment
   lands instantly and sticks. Verified in the browser.

   window.scrollTo() and scrollIntoView() stay unusable here, so
   this is also why every in-page link on this page goes through
   an onClick rather than relying on the browser's own fragment
   navigation.
   ============================================================ */
function jumpTo(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const root = document.documentElement;
  const previous = root.style.scrollBehavior;
  root.style.scrollBehavior = "auto";
  root.scrollTop = Math.max(
    el.getBoundingClientRect().top + root.scrollTop - 120,
    0
  );
  root.style.scrollBehavior = previous;
  window.history.replaceState(null, "", `#${id}`);
}

/** Anchor click → our own jump. Keeps the href real for copy-link and SEO. */
function anchorJump(id) {
  return (event) => {
    event.preventDefault();
    jumpTo(id);
  };
}

