/* A twelve-screen page with no sense of place. The rail is the fix: six stops
   down the left margin, the one you are in lit, and — once anything has been
   ticked — a ring showing how much of the material is behind you. Desktop
   only; on a narrow screen it would be another thing competing for a gutter
   that isn't there.

   "Which section am I in" is answered by the last stop whose top has passed
   the middle of the screen, not by whichever element has the most of itself
   visible: these sections differ in height by a factor of ten, and comparing
   intersection ratios just meant the shortest one always won. */
function SectionRail({ pct, done, total }) {
  const [at, setAt] = useState(RAIL_STOPS[0].id);

  useEffect(() => {
    let frame = 0;

    const measure = () => {
      frame = 0;
      const line = window.innerHeight * 0.4;
      let current = RAIL_STOPS[0].id;
      RAIL_STOPS.forEach((st) => {
        const el = document.getElementById(st.id);
        if (el && el.getBoundingClientRect().top <= line) current = st.id;
      });
      setAt(current);
    };

    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };

    measure();
    /* Capture, because this site does not always scroll the window — where a
       container scrolls instead, the scroll event never reaches window on the
       bubble phase (scroll doesn't bubble), but capture still sees it. */
    window.addEventListener("scroll", onScroll, {
      passive: true,
      capture: true,
    });
    window.addEventListener("resize", onScroll, { passive: true });
    return () => {
      if (frame) cancelAnimationFrame(frame);
      window.removeEventListener("scroll", onScroll, { capture: true });
      window.removeEventListener("resize", onScroll);
    };
  }, []);

  return (
    <nav className="lrn-srail" aria-label="Sections of this page">
      {total > 0 && (
        <span
          className="lrn-srail-pct"
          style={{ "--p": `${pct}%` }}
          title={`${done} of ${total} stages done`}
        >
          <b>{pct}%</b>
        </span>
      )}
      {RAIL_STOPS.map((st) => (
        <button
          key={st.id}
          type="button"
          className={`lrn-srail-stop${at === st.id ? " on" : ""}`}
          onClick={() => jumpTo(st.id)}
          aria-current={at === st.id ? "true" : undefined}
        >
          <i aria-hidden="true" />
          <span>{st.label}</span>
        </button>
      ))}
    </nav>
  );
}

