import React, { useMemo, useState } from "react";
import { TOKEN_SPLITS, TOKEN_PRESETS } from "../learnViz";

/* 0.1 — Tokens. Type a word, watch it break into pieces the model
   actually sees. The strawberry preset is the whole point: the model
   is never shown three separate r's, so counting them is a task it was
   structurally set up to fail. */

// Illustrative splitter. Known words come from the authored table; anything
// else falls back to a crude subword heuristic so typing still does something.
function split(text) {
  const key = text.toLowerCase().trim();
  if (TOKEN_SPLITS[key]) return TOKEN_SPLITS[key];
  if (!key) return [];
  return key
    .split(/(\s+)/)
    .filter((s) => s.length)
    .flatMap((word, i) => {
      const lead = i > 0 && /^\s+$/.test(word);
      if (/^\s+$/.test(word)) return [];
      const w = (i > 0 ? " " : "") + word;
      if (w.trim().length <= 6) return [w];
      // break long words every ~4 chars — not real BPE, just the right shape
      const parts = [];
      for (let j = 0; j < w.length; j += 4) parts.push(w.slice(j, j + 4));
      return parts;
    });
}

export default function Tokenizer() {
  const [text, setText] = useState("strawberry");
  const tokens = useMemo(() => split(text), [text]);
  const rCount = (text.match(/r/gi) || []).length;

  return (
    <div className="viz">
      <div className="viz-controls">
        <label className="viz-label" htmlFor="tok-in">
          Type anything
        </label>
        <input
          id="tok-in"
          className="viz-input"
          value={text}
          onChange={(e) => setText(e.target.value.slice(0, 40))}
          spellCheck="false"
        />
        <div className="viz-presets">
          {TOKEN_PRESETS.map((p) => (
            <button
              key={p}
              type="button"
              className={`viz-chip ${text === p ? "on" : ""}`}
              onClick={() => setText(p)}
            >
              {p}
            </button>
          ))}
        </div>
      </div>

      <div className="tok-out" aria-live="polite">
        {tokens.length === 0 && <span className="viz-muted">…</span>}
        {tokens.map((t, i) => (
          <span key={i} className="tok" style={{ "--i": i % 6 }}>
            <span className="tok-text">{t.replace(/ /g, "␣")}</span>
            <span className="tok-id">#{1000 + ((i * 7919) % 8000)}</span>
          </span>
        ))}
      </div>

      <p className="viz-note">
        {tokens.length} token{tokens.length === 1 ? "" : "s"} — not{" "}
        {text.replace(/\s/g, "").length} letters.
        {/r/i.test(text) && (
          <>
            {" "}
            You can see {rCount} “r” in the text; the model sees{" "}
            {tokens.filter((t) => /r/i.test(t)).length} chunk
            {tokens.filter((t) => /r/i.test(t)).length === 1 ? "" : "s"} that
            happen to contain one. That is the whole spelling problem.
          </>
        )}
      </p>
      <p className="viz-caveat">
        Illustrative splits — every model has its own vocabulary, so the exact
        pieces differ. The behaviour does not.
      </p>
    </div>
  );
}
