import React, { useEffect, useRef, useState } from "react";

import "./FractalBloom.css";

/* A tree that draws itself, branch by branch, leans toward the pointer, and
   drops the occasional petal.

   Ported from the shadcn/Tailwind original to this codebase's stack — plain
   JS, a stylesheet instead of utility classes, no framer-motion — with the
   changes it needed to live inside a page rather than own the viewport:

   1. It fills its own box, not `window.innerWidth/Height`, so it can sit in
      the empty half of a hero.
   2. The canvas is transparent. The original painted an opaque slate fill
      every frame for its trail effect, which would have buried the wash
      already behind it.
   3. It stops: idle once grown and settled, dead while off screen, and it
      doesn't start at all until the page it is decorating has loaded.
   4. Branches in one colour, a crown of blooms in another, and every so
      often one comes loose and falls. */

const MAX_DEPTH = 10;
const GROW_PER_FRAME = 0.04;
const LERP = 0.09;

/* Rare on purpose — one every few seconds, never more than a handful in the
   air. Petals raining down would turn a quiet hero into a screensaver. */
const PETAL_EVERY = [4200, 9000];
const PETAL_MAX = 5;

/* A stable pseudo-random value for a given branch. Every branch has its own
   id — the trunk is 1, its children 2 and 3, theirs 4..7 — so the shape is
   varied but identical on every frame and every reload. A perfectly mirrored
   fractal is what makes this kind of drawing look generated. */
function wobble(seed, salt) {
  const n = Math.sin(seed * 12.9898 + salt * 78.233) * 43758.5453;
  return n - Math.floor(n);
}

function toRgb(value, fallback) {
  const hex = String(value || "").trim();
  if (/^#[0-9a-f]{6}$/i.test(hex)) {
    const n = parseInt(hex.slice(1), 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }
  if (/^#[0-9a-f]{3}$/i.test(hex)) {
    return {
      r: parseInt(hex[1] + hex[1], 16),
      g: parseInt(hex[2] + hex[2], 16),
      b: parseInt(hex[3] + hex[3], 16),
    };
  }
  return fallback;
}

/* Nothing is drawn, measured or listened for until the page has finished
   loading and the browser has a spare moment. The tree is the least
   important thing on the page it decorates. */
function useDeferred(enabled) {
  const [ready, setReady] = useState(!enabled);

  useEffect(() => {
    if (!enabled) return undefined;
    let idle = 0;
    let timer = 0;

    const go = () => {
      if (typeof window.requestIdleCallback === "function") {
        idle = window.requestIdleCallback(() => setReady(true), {
          timeout: 1200,
        });
      } else {
        timer = setTimeout(() => setReady(true), 300);
      }
    };

    if (document.readyState === "complete") go();
    else window.addEventListener("load", go, { once: true });

    return () => {
      window.removeEventListener("load", go);
      if (idle && typeof window.cancelIdleCallback === "function") {
        window.cancelIdleCallback(idle);
      }
      if (timer) clearTimeout(timer);
    };
  }, [enabled]);

  return ready;
}

/* Hiding it in CSS would still mount a canvas and run an observer on a phone.
   This keeps it out of the tree entirely below the width where it earns its
   place, and puts it back if the window grows. */
function useWide(minWidth) {
  const query = `(min-width: ${minWidth}px)`;
  const [wide, setWide] = useState(() => {
    if (!minWidth) return true;
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia(query).matches;
  });

  useEffect(() => {
    if (!minWidth || typeof window === "undefined" || !window.matchMedia) {
      return undefined;
    }
    const mq = window.matchMedia(query);
    const onChange = (e) => setWide(e.matches);
    setWide(mq.matches);
    /* Safari only grew addEventListener on MediaQueryList in 14. */
    if (mq.addEventListener) mq.addEventListener("change", onChange);
    else mq.addListener(onChange);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener("change", onChange);
      else mq.removeListener(onChange);
    };
  }, [minWidth, query]);

  return wide;
}

export default function FractalBloom({
  className = "",
  /* The branches. */
  color = "#4db6ac",
  /* The crown, and the petals that come off it. */
  bloom = "#e4a853",
  /* How much of the box's height the trunk takes. */
  trunk = 0.2,
  /* Where the trunk stands, across the box: 0.5 is the middle. Pushing it off
     centre lets the canopy spread into space the trunk itself shouldn't
     occupy — a wide box with the trunk over to one side. */
  originX = 0.5,
  /* Wait for window load before doing anything at all. */
  defer = true,
  /* Below this viewport width the component does not render. */
  minWidth = 0,
  ...rest
}) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const colorRef = useRef({ color, bloom });
  colorRef.current = { color, bloom };
  const wide = useWide(minWidth);
  const ready = useDeferred(defer) && wide;

  useEffect(() => {
    if (!ready) return undefined;
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return undefined;
    const ctx = canvas.getContext("2d");
    if (!ctx) return undefined;

    const reduced =
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let raf = 0;
    let spawn = 0;
    let onScreen = true;
    let size = { w: 0, h: 0 };
    let depth = reduced ? MAX_DEPTH : 0;
    let last = 0;

    /* Where the pointer is, where the branches have leaned to so far, and
       whether it is anywhere near — the gap between the first two is what
       makes the lean feel like weight. */
    const target = { x: -9999, y: -9999 };
    const eased = { x: -9999, y: -9999 };

    /* Collected on the frame the tree finishes growing, so a falling petal
       starts from somewhere a petal actually is. */
    let tips = [];
    const petals = [];

    const setSize = () => {
      const r = wrap.getBoundingClientRect();
      const w = Math.round(r.width);
      const h = Math.round(r.height);
      if (!w || !h) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      size = { w, h };
    };

    const draw = (now) => {
      const { w: W, h: H } = size;
      if (!W || !H) return;
      const c = toRgb(colorRef.current.color, { r: 77, g: 182, b: 172 });
      const b = toRgb(colorRef.current.bloom, { r: 228, g: 168, b: 83 });
      const reach = Math.min(W, H) * 0.95;
      /* Smaller boxes get a shorter tree — ten levels in 300px is a smudge. */
      const levels = W < 380 ? MAX_DEPTH - 2 : MAX_DEPTH;
      const cap = Math.min(depth, levels);

      ctx.clearRect(0, 0, W, H);
      ctx.lineCap = "round";
      const collecting = cap >= levels;
      if (collecting) tips = [];

      const branch = (x, y, angle, length, d, seed) => {
        if (d > cap) return;

        const endX = x + Math.cos(angle) * length;
        const endY = y + Math.sin(angle) * length;

        /* The last stretch of a branch grows in, so the tree unfolds
           continuously rather than a level at a time. */
        const partial = Math.min(1, cap - d + 1);
        const tipX = x + (endX - x) * partial;
        const tipY = y + (endY - y) * partial;

        const t = d / levels;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(tipX, tipY);
        ctx.strokeStyle = `rgba(${c.r},${c.g},${c.b},${(
          (1 - t) * 0.5 +
          0.08
        ).toFixed(3)})`;
        ctx.lineWidth = Math.max(0.6, (1 - t) * 2.6);
        ctx.stroke();

        /* The crown. The outer three levels carry blooms rather than only
           the very last one, and the higher up the branch is the bigger and
           brighter its flower — which is what makes it a canopy instead of a
           dusting of dots. */
        if (d >= levels - 3 && partial > 0.85) {
          const up = 1 - Math.min(1, tipY / (H * 0.9));
          const near = eased.x > -9000 ? Math.hypot(tipX - eased.x, tipY - eased.y) : 1e9;
          const lit = Math.max(0, 1 - near / (reach * 0.55));
          const wa = wobble(seed, 3);
          const r =
            (0.9 + wa * 1.5) * (0.5 + up * 0.9) * (1 + lit * 0.5);
          const a = (0.2 + up * 0.5) * (0.7 + lit * 0.6);

          ctx.beginPath();
          ctx.arc(tipX, tipY, r, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(${b.r},${b.g},${b.b},${Math.min(
            0.95,
            a
          ).toFixed(3)})`;
          ctx.fill();

          /* A soft halo on the biggest, highest flowers only. */
          if (up > 0.55 && wa > 0.45) {
            ctx.beginPath();
            ctx.arc(tipX, tipY, r * 3.4, 0, Math.PI * 2);
            ctx.fillStyle = `rgba(${b.r},${b.g},${b.b},${(
              a * 0.14
            ).toFixed(3)})`;
            ctx.fill();
          }

          if (collecting && d === levels && up > 0.35) {
            tips.push({ x: tipX, y: tipY, r });
          }
        }

        if (d >= levels) return;

        /* How hard this branch leans, and which way, is the pointer's doing. */
        const dist = Math.hypot(endX - eased.x, endY - eased.y);
        const pull = Math.max(0, 1 - dist / reach);
        const spread = Math.PI / 9 + (Math.PI / 8) * pull;

        /* Each fork is a little uneven — one arm longer, both angles nudged.
           Same numbers every frame, so the tree doesn't shimmer. */
        const wl = wobble(seed, 1);
        const wr = wobble(seed, 2);

        branch(
          tipX,
          tipY,
          angle - spread * (0.8 + wl * 0.5),
          length * (0.72 + wl * 0.1),
          d + 1,
          seed * 2
        );
        branch(
          tipX,
          tipY,
          angle + spread * (0.8 + wr * 0.5),
          length * (0.72 + wr * 0.1),
          d + 1,
          seed * 2 + 1
        );
      };

      branch(W * originX, H, -Math.PI / 2, H * trunk, 0, 1);

      /* ---- the petals that have come loose */
      const dt = last ? Math.min(64, now - last) : 16;
      for (let i = petals.length - 1; i >= 0; i--) {
        const p = petals[i];
        p.t += dt;
        p.y += p.vy * (dt / 16);
        p.sway += 0.02 * (dt / 16);
        const x = p.x + Math.sin(p.sway) * p.drift;
        const life = 1 - p.t / p.life;
        if (life <= 0 || p.y > H + 12) {
          petals.splice(i, 1);
          continue;
        }
        ctx.beginPath();
        ctx.arc(x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${b.r},${b.g},${b.b},${(
          Math.min(1, life * 1.6) * 0.5
        ).toFixed(3)})`;
        ctx.fill();
      }
      last = now;
    };

    const frame = (now) => {
      const moving =
        Math.abs(eased.x - target.x) > 0.4 ||
        Math.abs(eased.y - target.y) > 0.4;

      if (moving) {
        eased.x =
          eased.x < -9000 ? target.x : eased.x + (target.x - eased.x) * LERP;
        eased.y =
          eased.y < -9000 ? target.y : eased.y + (target.y - eased.y) * LERP;
      }
      if (depth < MAX_DEPTH) depth = Math.min(MAX_DEPTH, depth + GROW_PER_FRAME);

      draw(now);

      /* Grown, settled, nothing in the air: stop until something happens. */
      if (!moving && depth >= MAX_DEPTH && petals.length === 0) {
        raf = 0;
        last = 0;
        return;
      }
      raf = requestAnimationFrame(frame);
    };

    const kick = () => {
      if (!raf && onScreen) raf = requestAnimationFrame(frame);
    };

    const dropPetal = () => {
      if (petals.length >= PETAL_MAX || !tips.length) return;
      const from = tips[Math.floor(Math.random() * tips.length)];
      petals.push({
        x: from.x,
        y: from.y,
        r: Math.max(1, from.r * 0.85),
        vy: 0.22 + Math.random() * 0.26,
        drift: 6 + Math.random() * 16,
        sway: Math.random() * Math.PI * 2,
        t: 0,
        life: 9000 + Math.random() * 6000,
      });
      kick();
    };

    const scheduleDrop = () => {
      const [lo, hi] = PETAL_EVERY;
      spawn = setTimeout(() => {
        if (onScreen) dropPetal();
        scheduleDrop();
      }, lo + Math.random() * (hi - lo));
    };

    setSize();
    draw(performance.now());

    let ro = null;
    if (typeof ResizeObserver !== "undefined") {
      ro = new ResizeObserver(() => {
        setSize();
        /* A resize mid-growth would otherwise redraw a half-grown tree at the
           wrong scale and leave it there. */
        if (!raf) draw(performance.now());
      });
      ro.observe(wrap);
    }

    if (reduced) {
      return () => {
        if (ro) ro.disconnect();
      };
    }

    const onMove = (e) => {
      const r = wrap.getBoundingClientRect();
      target.x = e.clientX - r.left;
      target.y = e.clientY - r.top;
      kick();
    };

    const onLeave = () => {
      target.x = -9999;
      target.y = -9999;
      kick();
    };

    window.addEventListener("mousemove", onMove, { passive: true });
    document.addEventListener("mouseleave", onLeave);

    /* Off screen it does nothing at all — this sits at the top of a very long
       page, and without the flag the mousemove listener would wake it from
       anywhere on that page. */
    let io = null;
    if (typeof IntersectionObserver !== "undefined") {
      io = new IntersectionObserver(
        ([e]) => {
          onScreen = e.isIntersecting;
          if (onScreen) kick();
          else if (raf) {
            cancelAnimationFrame(raf);
            raf = 0;
            last = 0;
          }
        },
        { rootMargin: "60px" }
      );
      io.observe(wrap);
    }

    kick();
    scheduleDrop();

    return () => {
      if (raf) cancelAnimationFrame(raf);
      if (spawn) clearTimeout(spawn);
      window.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseleave", onLeave);
      if (ro) ro.disconnect();
      if (io) io.disconnect();
    };
  }, [ready, trunk, originX]);

  if (!wide) return null;

  return (
    <div
      ref={wrapRef}
      className={`fbloom${ready ? " is-live" : ""}${
        className ? ` ${className}` : ""
      }`}
      aria-hidden="true"
      {...rest}
    >
      <canvas ref={canvasRef} className="fbloom-canvas" />
    </div>
  );
}
